@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* Step Indicator *@
    <nav class="step-indicator mb-4" aria-label="Application steps">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <div class="step-item @status" @onclick="() => NavigateToStep(stepIndex)" role="button"
                 tabindex="@(status == "completed" ? 0 : -1)"
                 aria-current="@(stepIndex == currentStep ? "step" : null)">
                <div class="step-circle">
                    @if (status == "completed")
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
        }
    </nav>

    @* Validation / error banner *@
    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger" role="alert">@errorMessage</div>
    }

    @* Step content *@
    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo" />
            <div class="d-flex justify-content-end mt-3">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                    @if (isValidating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Next
                </button>
            </div>
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries" />
            <div class="d-flex justify-content-between mt-3">
                <button class="btn btn-outline-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
            </div>
            break;

        case 2:
            <ReferencesStep References="references" />
            <div class="d-flex justify-content-between mt-3">
                <button class="btn btn-outline-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
            </div>
            break;

        case 3:
            <CoverLetterStep @bind-CoverLetter="coverLetter" MaxLength="CoverLetterMaxLength" />
            <div class="d-flex justify-content-between mt-3">
                <button class="btn btn-outline-secondary" @onclick="Back">Back</button>
                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
            </div>
            break;

        case 4:
            <ReviewStep PersonalInfo="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="coverLetter"
                        OnEditSection="GoToStep"
                        IsSubmitting="isSubmitting"
                        IsSubmitted="isSubmitted"
                        ApplicationId="applicationId"
                        OnSubmit="SubmitApplication" />
            @if (!isSubmitted)
            {
                <div class="d-flex justify-content-between mt-3">
                    <button class="btn btn-outline-secondary" @onclick="Back" disabled="@isSubmitting">Back</button>
                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@isSubmitting">
                        @if (isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Submit Application
                    </button>
                </div>
            }
            break;
    }
</div>

