+        case 1:
+            <WorkHistoryStep Entries="workEntries" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="Back">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+            </div>
+            break;
+
+        case 2:
+            <ReferencesStep References="references" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="Back">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+            </div>
+            break;
+
+        case 3:
+            <CoverLetterStep @bind-CoverLetter="coverLetter" MaxLength="CoverLetterMaxLength" />
+            <div class="d-flex justify-content-between mt-3">
+                <button class="btn btn-outline-secondary" @onclick="Back">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
+            </div>
+            break;
+
+        case 4:
+            <ReviewStep PersonalInfo="personalInfo"
+                        WorkEntries="workEntries"
+                        References="references"
+                        CoverLetter="coverLetter"
+                        OnEditSection="GoToStep"
+                        IsSubmitting="isSubmitting"
+                        IsSubmitted="isSubmitted"
+                        ApplicationId="applicationId"
+                        OnSubmit="SubmitApplication" />
+            @if (!isSubmitted)
+            {
+                <div class="d-flex justify-content-between mt-3">
+                    <button class="btn btn-outline-secondary" @onclick="Back" disabled="@isSubmitting">Back</button>
+                    <button class="btn btn-success" @onclick="SubmitApplication" disabled="@isSubmitting">
+                        @if (isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                        Submit Application
+                    </button>
+                </div>
+            }
+            break;
+    }
+</div>
+
+@code {
+    private static readonly string[] StepNames =
+        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
+
+    private const int CoverLetterMaxLength = 2000;
+
+    private int currentStep;
+    private int highestCompletedStep = -1;
+    private string? errorMessage;
+
+    // Form state
+    private PersonalInfoModel personalInfo = new();
+    private List<WorkEntryModel> workEntries = [new()];
+    private List<ReferenceModel> references = [new(), new()];
+    private string coverLetter = "";
+
+    // UI state
+    private bool isValidating;
+    private bool isSubmitting;
+    private bool isSubmitted;
+    private int? applicationId;
+
+    private string GetStepStatus(int step)
+    {
+        if (step == currentStep) return "active";
+        if (step <= highestCompletedStep) return "completed";
+        return "dimmed";
+    }
+
+    private void NavigateToStep(int step)
+    {
+        if (step <= highestCompletedStep)
+        {
+            currentStep = step;
+            errorMessage = null;
+        }
+    }
+
+    private void GoToStep(int step)
+    {
+        currentStep = step;
+        errorMessage = null;
+    }
+
+    private void Back()
+    {
+        if (currentStep > 0)
+        {
+            currentStep--;
+            errorMessage = null;
+        }
+    }
+
+    private void MarkCompleted(int step)
+    {
+        if (step > highestCompletedStep)
+            highestCompletedStep = step;
+    }
+
+    // Step 1 validation
+    private async Task NextFromPersonalInfo()
+    {
+        errorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(personalInfo.FullName))
+        { errorMessage = "Full name is required."; return; }
+        if (string.IsNullOrWhiteSpace(personalInfo.Email))
+        { errorMessage = "Email is required."; return; }
+        if (string.IsNullOrWhiteSpace(personalInfo.Phone))
+        { errorMessage = "Phone number is required."; return; }
+        if (string.IsNullOrWhiteSpace(personalInfo.Address))
+        { errorMessage = "Address is required."; return; }
+
+        isValidating = true;
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
+            if (!emailValid)
+            { errorMessage = "Please enter a valid email address."; return; }
+        }
+        finally { isValidating = false; }
+
+        MarkCompleted(0);
+        currentStep = 1;
+    }
+
+    // Step 2 validation
+    private void NextFromWorkHistory()
+    {
+        errorMessage = null;
+        foreach (var entry in workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
+            { errorMessage = "Each work entry requires a company name and job title."; return; }
+        }
+        MarkCompleted(1);
+        currentStep = 2;
+    }
+
+    // Step 3 validation
+    private void NextFromReferences()
+    {
+        errorMessage = null;
+        if (references.Count < 2)
+        { errorMessage = "At least 2 references are required."; return; }
+        foreach (var r in references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
+            { errorMessage = "Each reference requires a name and email."; return; }
+        }
+        MarkCompleted(2);
+        currentStep = 3;
+    }
+
+    // Step 4 validation
+    private void NextFromCoverLetter()
+    {
+        errorMessage = null;
+        if (string.IsNullOrWhiteSpace(coverLetter))
+        { errorMessage = "Please write a cover letter."; return; }
+        if (coverLetter.Length > CoverLetterMaxLength)
+        { errorMessage = $"Cover letter must not exceed {CoverLetterMaxLength} characters."; return; }
+        MarkCompleted(3);
+        currentStep = 4;
+    }
+
+    // Submit
+    private async Task SubmitApplication()
+    {
+        if (isSubmitting || isSubmitted) return;
+        isSubmitting = true;
+        errorMessage = null;
+
+        try
+        {
+            var application = new JobApplication(
+                personalInfo.ToRecord(),
+                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
+                references.Select(r => r.ToRecord()).ToList(),
+                coverLetter
+            );
+
+            applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+            MarkCompleted(4);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+}
+

