.step-indicator {
    display: flex;
    justify-content: space-between;
    position: relative;
}

.step-indicator::before {
    content: '';
    position: absolute;
    top: 18px;
    left: 36px;
    right: 36px;
    height: 2px;
    background: #dee2e6;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    z-index: 1;
    cursor: default;
    user-select: none;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.85rem;
    border: 2px solid #dee2e6;
    background: #fff;
    transition: all 0.2s;
}

.step-label {
    margin-top: 6px;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
    transition: color 0.2s;
}

/* Active step */
.step-item.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

/* Completed step */
.step-item.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.completed:hover .step-circle {
    box-shadow: 0 0 0 3px rgba(25, 135, 84, 0.25);
}

/* Dimmed / future step */
.step-item.dimmed .step-circle {
    border-color: #dee2e6;
    color: #adb5bd;
    background: #f8f9fa;
}

.step-item.dimmed .step-label {
    color: #adb5bd;
}

