toolArgs.file_text:
@using sv_4be79e141f2d4ef7a10f75578d78b693.Models

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Work History</h5>

        @for (int i = 0; i < Entries.Count; i++)
        {
            var index = i;
            var entry = Entries[index];

            <div class="border rounded p-3 mb-3 bg-light">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h6 class="mb-0">Position @(index + 1)</h6>
                    @if (Entries.Count > 1)
                    {
                        <button type="button" class="btn btn-sm btn-outline-danger" @onclick="() => RemoveEntry(index)">
                            Remove
                        </button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Company <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="entry.Company" @bind:event="oninput" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Job Title <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="entry.Title" @bind:event="oninput" />
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date</label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end pb-2">
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="current-@index"
                                   @bind="entry.IsCurrent" />
                            <label class="form-check-label" for="current-@index">Currently working here</label>
                        </div>
                    </div>
                </div>

                <div class="mb-0">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description" @bind:event="oninput"></textarea>
                </div>
            </div>
        }

        <button type="button" class="btn btn-outline-primary" @onclick="AddEntry">
            + Add Another Position
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }
}

@using sv_4be79e141f2d4ef7a10f75578d78b693.Models

<div class="card">
    <div class="card-body">
        <h5 class="card-title">References</h5>

        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            var reference = References[index];

            <div class="border rounded p-3 mb-3 bg-light">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h6 class="mb-0">Reference @(index + 1)</h6>
                    @if (References.Count > 2)
                    {
                        <button type="button" class="btn btn-sm btn-outline-danger"
                                @onclick="() => RemoveReference(index)">
                            Remove
                        </button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="reference.Name" @bind:event="oninput" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Relationship</label>
                        <input type="text" class="form-control" @bind="reference.Relationship" @bind:event="oninput"
                               placeholder="e.g., Former Manager" />
                    </div>
                </div>

                <div class="row mb-0">
                    <div class="col-md-6">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="reference.Email" @bind:event="oninput" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone</label>
                        <input type="tel" class="form-control" @bind="reference.Phone" @bind:event="oninput" />
                    </div>
                </div>
            </div>
        }

        @if (References.Count < 3)
        {
            <button type="button" class="btn btn-outline-primary" @onclick="AddReference">
                + Add Reference
            </button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }
}

@using sv_4be79e141f2d4ef7a10f75578d78b693.Models

@if (IsSubmitted)
{
    <div class="card border-success">
        <div class="card-body text-center py-5">
            <div class="text-success mb-3" style="font-size: 3rem;">✓</div>
            <h4 class="text-success">Application Submitted Successfully!</h4>
            <p class="text-muted mb-1">Your application has been received.</p>
            <p class="fs-5">Application ID: <strong>@ApplicationId</strong></p>
        </div>
    </div>
}
else
{
    <div class="card">
        <div class="card-body">
            <h5 class="card-title">Review Your Application</h5>

            @* Personal Info *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h6 class="mb-0">Personal Information</h6>
                    <button type="button" class="btn btn-sm btn-link p-0" @onclick='() => OnEditSection.InvokeAsync(0)'>Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@PersonalInfo.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@PersonalInfo.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@PersonalInfo.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@PersonalInfo.Address</dd>
                </dl>
            </div>

            @* Work History *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h6 class="mb-0">Work History</h6>
                    <button type="button" class="btn btn-sm btn-link p-0" @onclick='() => OnEditSection.InvokeAsync(1)'>Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-2 border-start border-3">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1 small">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            @* References *@
            <div class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h6 class="mb-0">References</h6>
                    <button type="button" class="btn btn-sm btn-link p-0" @onclick='() => OnEditSection.InvokeAsync(2)'>Edit</button>
                </div>
                @foreach (var r in References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong>
                        @if (!string.IsNullOrWhiteSpace(r.Relationship))
                        {
                            <span class="text-muted"> — @r.Relationship</span>
                        }
                        <br />
                        <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $" · {r.Phone}" : "")</small>
                    </div>
                }
            </div>

            @* Cover Letter *@
            <div class="mb-2">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                    <h6 class="mb-0">Cover Letter</h6>
                    <button type="button" class="btn btn-sm btn-link p-0" @onclick='() => OnEditSection.InvokeAsync(3)'>Edit</button>
                </div>
                <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
}

